(5136757, 746584, 36006, '<td valign="top">First of all...where is the bokeh?<br/> <br/>Secondly...why are you trying to make me care for the back side of someones head? I can care less for the curly hair. Hair has no emotional impact, no matter how you try.<br/> <br/>The crop is off as well.<br/> <br/>The only good thing in this image is the dof, the rim light off the face which I would of wanted to see more for the emotional value, and the key light kicking off the shoulder.<br/> <br/>Not going to do so well in this challenge, especially on this web site.<br/> <br/>Good luck, happy holidays.</td>', 'First of all...where is the bokeh? Secondly...why are you trying to make me care for the back side of someones head? I can care less for the curly hair. Hair has no emotional impact, no matter how you try. The crop is off as well. The only good thing in this image is the dof, the rim light off the face which I would of wanted to see more for the emotional value, and the key light kicking off the shoulder. Not going to do so well in this challenge, especially on this web site. Good luck, happy holidays.', '2008-12-17 09:37:30.000000', NULL, 1),
(5136759, 747984, 65234, '<td valign="top">Very pretty bokeh and you got some light on your foreground, too.</td>', 'Very pretty bokeh and you got some light on your foreground, too.', '2008-12-17 09:37:40.000000', NULL, 1),
(5136771, 747953, 65234, '<td valign="top">Looks like flash reflected in his eyes; I try to bounce flash with animals because even a diffuser won''t eliminate that weird look in the eyes.  The bokeh is a bit overwhelming, like it''s slowly absorbing him into itself.</td>', 'Looks like flash reflected in his eyes; I try to bounce flash with animals because even a diffuser won''t eliminate that weird look in the eyes.  The bokeh is a bit overwhelming, like it''s slowly absorbing him into itself.', '2008-12-17 09:40:58.000000', NULL, 1),
(5136775, 747072, 65234, '<td valign="top">Pretty berry!</td>', 'Pretty berry!', '2008-12-17 09:42:44.000000', NULL, 1),
(5136780, 747736, 65234, '<td valign="top">Oooh, sparkly spider, too!  Wonderfully sci-fi colors here and it feels like it''s pulling me in =:-O</td>', 'Oooh, sparkly spider, too!  Wonderfully sci-fi colors here and it feels like it''s pulling me in =:-O', '2008-12-17 09:44:56.000000', NULL, 1),
(5136785, 747942, 65234, '<td valign="top">Looks like an <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=5112" rel="nofollow" target="_blank">Ursula</a> (and I mean that as a high compliment).  Really beautiful.</td>', 'Looks like an  Ursula (and I mean that as a high compliment).  Really beautiful.', '2008-12-17 09:46:23.000000', NULL, 1),
(5136791, 747105, 65234, '<td valign="top">Those look suspiciously like soap bubbles in that glass!  I like the restricted color palette pulling it all together.</td>', 'Those look suspiciously like soap bubbles in that glass!  I like the restricted color palette pulling it all together.', '2008-12-17 09:47:57.000000', NULL, 1),
(5136792, 746566, 65234, '<td valign="top">Warm in many ways.</td>', 'Warm in many ways.', '2008-12-17 09:48:18.000000', NULL, 1),
(5136793, 747422, 65234, '<td valign="top">Lovely patterns.  My kind of shot.</td>', 'Lovely patterns.  My kind of shot.', '2008-12-17 09:48:50.000000', NULL, 1),
(5136796, 747903, 65234, '<td valign="top">For this challenge I''d like the background to set the scene or in some way complement the subject.  The dog looks fine but I''m not wowed by the background.</td>', 'For this challenge I''d like the background to set the scene or in some way complement the subject.  The dog looks fine but I''m not wowed by the background.', '2008-12-17 09:50:35.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5136797, 747857, 65234, '<td valign="top">Ghostly bokeh.  This is quite moody but not entirely depressing with the light patterns.</td>', 'Ghostly bokeh.  This is quite moody but not entirely depressing with the light patterns.', '2008-12-17 09:51:27.000000', NULL, 1),
(5136798, 747577, 65234, '<td valign="top">Like little ballerinas poised on tiptoe :-)</td>', 'Like little ballerinas poised on tiptoe :-)', '2008-12-17 09:51:54.000000', NULL, 1),
(5136799, 747232, 65234, '<td valign="top">Cooperative little model.  Almost looks like the eye on the right is pointed!</td>', 'Cooperative little model.  Almost looks like the eye on the right is pointed!', '2008-12-17 09:52:37.000000', NULL, 1),
(5136800, 747344, 65234, '<td valign="top">Great expression :-)  Bundled up kids always look cute.</td>', 'Great expression :-)  Bundled up kids always look cute.', '2008-12-17 09:53:24.000000', NULL, 1),
(5136803, 747933, 65234, '<td valign="top">Nice, subtle background.</td>', 'Nice, subtle background.', '2008-12-17 09:54:35.000000', NULL, 1),
(5136805, 747902, 65234, '<td valign="top">I just made cookies that look like that last weekend!  I had to immediately freeze them so there''d be some left by Christmas ;-)</td>', 'I just made cookies that look like that last weekend!  I had to immediately freeze them so there''d be some left by Christmas ;-)', '2008-12-17 09:55:26.000000', NULL, 1),
(5136807, 747940, 65234, '<td valign="top">Awesome eyeball!</td>', 'Awesome eyeball!', '2008-12-17 09:56:18.000000', NULL, 1),
(5136809, 746907, 65234, '<td valign="top">Tough exposure; I''d like to be able to see his/her eyes better.</td>', 'Tough exposure; I''d like to be able to see his/her eyes better.', '2008-12-17 09:57:48.000000', NULL, 1),
(5136818, 746521, 65234, '<td valign="top">Nice capture!  The birds are blending in to the yellow-green in the background; possibly a hue-shift from yellow-green to green and a slight desaturation of that would make the birds stand out more.</td>', 'Nice capture!  The birds are blending in to the yellow-green in the background; possibly a hue-shift from yellow-green to green and a slight desaturation of that would make the birds stand out more.', '2008-12-17 10:01:38.000000', NULL, 1),
(5136821, 747738, 65234, '<td valign="top">Whee!</td>', 'Whee!', '2008-12-17 10:02:15.000000', NULL, 1),
(5136824, 747735, 65234, '<td valign="top">I''m sure I won''t be the only one to mention that this is a bit small and that makes it harder to evaluate.  A full 640 pixels wide would be easier to see.</td>', 'I''m sure I won''t be the only one to mention that this is a bit small and that makes it harder to evaluate.  A full 640 pixels wide would be easier to see.', '2008-12-17 10:03:06.000000', NULL, 1),
(5136825, 747705, 65234, '<td valign="top">Nice job on getting the red color to stand out so well.</td>', 'Nice job on getting the red color to stand out so well.', '2008-12-17 10:03:37.000000', NULL, 1),
(5136827, 747858, 65234, '<td valign="top">Simple, but pretty.</td>', 'Simple, but pretty.', '2008-12-17 10:03:52.000000', NULL, 1),
(5136828, 747108, 65234, '<td valign="top">Love how he''s peeking into the image!</td>', 'Love how he''s peeking into the image!', '2008-12-17 10:04:20.000000', NULL, 1),
(5136831, 748025, 65234, '<td valign="top">Very nice patterns you got in the background with this DOF.  Iridescent bokeh :-)</td>', 'Very nice patterns you got in the background with this DOF.  Iridescent bokeh :-)', '2008-12-17 10:05:56.000000', NULL, 1),
(5136834, 747615, 88718, '<td valign="top">Looks like everything is out of focus here. Nice colours though</td>', 'Looks like everything is out of focus here. Nice colours though', '2008-12-17 10:06:53.000000', NULL, 1),
(5136840, 747773, 65234, '<td valign="top">Nice light patterns in the background.</td>', 'Nice light patterns in the background.', '2008-12-17 10:08:04.000000', NULL, 1),
(5136844, 747689, 65234, '<td valign="top">Beautiful capture.  For this challenge I''d like to see something more in the background, colors or patterns or light changes that hint at the setting or enhance my view of the bird.</td>', 'Beautiful capture.  For this challenge I''d like to see something more in the background, colors or patterns or light changes that hint at the setting or enhance my view of the bird.', '2008-12-17 10:09:45.000000', NULL, 1),
(5136845, 748040, 76198, '<td valign="top">Oh lord. Now I have to go vote on all the others so my vote will count!</td>', 'Oh lord. Now I have to go vote on all the others so my vote will count!', '2008-12-17 10:09:52.000000', NULL, 1),
(5136854, 747901, 76198, '<td valign="top">I think this would have rocked a square crop...</td>', 'I think this would have rocked a square crop...', '2008-12-17 10:13:55.000000', NULL, 1),
(5136855, 746298, 60614, '<td valign="top">Nice photo with some great colors but doesn''t have the bokeh feel.  This one seems to fit more in the Shallow DOF challenge.  Here is a sample of some bokeh with the out of focus point of lights that people are trying to achieve<a href="//en.wikipedia.org/wiki/File:Josefina_with_Bokeh.jpg" rel="nofollow" target="_blank">SampleBokeh</a></td>', 'Nice photo with some great colors but doesn''t have the bokeh feel.  This one seems to fit more in the Shallow DOF challenge.  Here is a sample of some bokeh with the out of focus point of lights that people are trying to achieveSampleBokeh', '2008-12-17 10:15:00.000000', NULL, 1),
(5136857, 747075, 76198, '<td valign="top">Great pic.</td>', 'Great pic.', '2008-12-17 10:15:25.000000', NULL, 1),
(5136858, 747911, 60614, '<td valign="top">You have some bokeh going on but the top seems very dark.  Could be my monitor.</td>', 'You have some bokeh going on but the top seems very dark.  Could be my monitor.', '2008-12-17 10:15:49.000000', NULL, 1),
(5136859, 747930, 76198, '<td valign="top">Do you know how much time I spent this fall trying to get this close to one!? ;)</td>', 'Do you know how much time I spent this fall trying to get this close to one!? ;)', '2008-12-17 10:17:06.000000', NULL, 1),
(5136862, 747621, 76198, '<td valign="top">my 1st 10 of the challenge. Beautiful.</td>', 'my 1st 10 of the challenge. Beautiful.', '2008-12-17 10:17:56.000000', NULL, 1),
(5136865, 747942, 76198, '<td valign="top">Either Ursula or a remarkably good homage. Either way a 10.</td>', 'Either Ursula or a remarkably good homage. Either way a 10.', '2008-12-17 10:19:32.000000', NULL, 1),
(5136897, 747592, 99981, '<td valign="top">You have a good bokeh there, and i don''t know if i''m wrong in my opinion, but the little girl (cutie model) is so more important in this photo than the bokeh. The part with the good bokeh is just too small. Lighting is great and colors too...i think you would have a amazing photo in another perspective. Maybe with the girl on her knees or on foot to get a higher vision of the fields of gold. Good luck!</td>', 'You have a good bokeh there, and i don''t know if i''m wrong in my opinion, but the little girl (cutie model) is so more important in this photo than the bokeh. The part with the good bokeh is just too small. Lighting is great and colors too...i think you would have a amazing photo in another perspective. Maybe with the girl on her knees or on foot to get a higher vision of the fields of gold. Good luck!', '2008-12-17 10:42:09.000000', NULL, 1),
(5136974, 746298, 60680, '<td valign="top">Clever</td>', 'Clever', '2008-12-17 11:17:29.000000', NULL, 1),
(5136975, 747988, 99981, '<td valign="top">Dear Mrs. Clause, <br/> <br/>I think you are a good object, but have just some small parts out of focus. There are so much christmas photos in this challenge, but i really like yours because you have a good bokeh on your back, maybe stronger colors would give you even more beauty!<br/> <br/>Merry Chirstmas,<br/> <br/>Pedro.</td>', 'Dear Mrs. Clause,  I think you are a good object, but have just some small parts out of focus. There are so much christmas photos in this challenge, but i really like yours because you have a good bokeh on your back, maybe stronger colors would give you even more beauty! Merry Chirstmas, Pedro.', '2008-12-17 11:17:30.000000', NULL, 1),
(5136989, 747553, 60680, '<td valign="top">Terrific idea 9</td>', 'Terrific idea 9', '2008-12-17 11:21:15.000000', NULL, 1),
(5137037, 746893, 92545, '<td valign="top">I guess I''m not seeing why this is in this challenge.</td>', 'I guess I''m not seeing why this is in this challenge.', '2008-12-17 11:37:28.000000', NULL, 1),
(5137050, 747631, 92545, '<td valign="top">I like the idea and the bokeh is nice, but the composition really bugs me for some reason.  The G just ends too abruptly.</td>', 'I like the idea and the bokeh is nice, but the composition really bugs me for some reason.  The G just ends too abruptly.', '2008-12-17 11:41:21.000000', NULL, 1),
(5137051, 746285, 92545, '<td valign="top">Nice, but I''m not seeing the bokeh.</td>', 'Nice, but I''m not seeing the bokeh.', '2008-12-17 11:42:30.000000', NULL, 1),
(5137055, 747735, 92545, '<td valign="top">This probably would have been better with a larger size.  Make the most of what you have to work with.</td>', 'This probably would have been better with a larger size.  Make the most of what you have to work with.', '2008-12-17 11:43:46.000000', NULL, 1),
(5137070, 747108, 92545, '<td valign="top">I think this could have been better.  It has the potential to be a great shot, but there''s just not enough of the cardinal for me.  Maybe a less severe crop would have done better.</td>', 'I think this could have been better.  It has the potential to be a great shot, but there''s just not enough of the cardinal for me.  Maybe a less severe crop would have done better.', '2008-12-17 11:47:10.000000', NULL, 1),
(5137071, 747736, 92545, '<td valign="top">If the spider were in a little better focus, this could have been fantastic.</td>', 'If the spider were in a little better focus, this could have been fantastic.', '2008-12-17 11:47:47.000000', NULL, 1),
(5137076, 748040, 92545, '<td valign="top">I''m afraid this shot is just too small to see anything.</td>', 'I''m afraid this shot is just too small to see anything.', '2008-12-17 11:50:07.000000', NULL, 1),
(5137080, 747896, 99981, '<td valign="top">I like the Bokeh but i think you missed a lot on the light, because the boy on the front is really dark.</td>', 'I like the Bokeh but i think you missed a lot on the light, because the boy on the front is really dark.', '2008-12-17 11:50:38.000000', NULL, 1),
(5137082, 748026, 100216, '<td valign="top">i really like it, but next time you should use more light and colors!</td>', 'i really like it, but next time you should use more light and colors!', '2008-12-17 11:51:39.000000', NULL, 1),
(5137089, 747822, 92545, '<td valign="top">The bokeh is really pleasing here, but the lighting ends up a little harsh on the subject.</td>', 'The bokeh is really pleasing here, but the lighting ends up a little harsh on the subject.', '2008-12-17 11:55:21.000000', NULL, 1),
(5137128, 747946, 92545, '<td valign="top">What a great shot for a bokeh challenge.  Love it.  After taking a second look, I''m bumping this up to a 9.</td>', 'What a great shot for a bokeh challenge.  Love it.  After taking a second look, I''m bumping this up to a 9.', '2008-12-17 12:12:41.000000', NULL, 1),
(5137133, 747940, 92545, '<td valign="top">I really love this.  I just got a macro lens and I really hope I can get some shots like this.  Wonderful.  9</td>', 'I really love this.  I just got a macro lens and I really hope I can get some shots like this.  Wonderful.  9', '2008-12-17 12:12:51.000000', NULL, 1),
(5137135, 748038, 92545, '<td valign="top">There is just something pleasing about this.  Perfect bokeh.  I love it.  8</td>', 'There is just something pleasing about this.  Perfect bokeh.  I love it.  8', '2008-12-17 12:12:54.000000', NULL, 1),
(5137136, 747947, 92545, '<td valign="top">My favorite of all the Christmas shots here.  The bokeh may not be so pronounced, but you capture the mood of Christmas perfectly.  The lighting might be a litle harsh on the socks.  The background has such a nice warm glow, that I think a warmer tone to the foreground could have helped.  I still love it.  I''m giving it a solid 9.</td>', 'My favorite of all the Christmas shots here.  The bokeh may not be so pronounced, but you capture the mood of Christmas perfectly.  The lighting might be a litle harsh on the socks.  The background has such a nice warm glow, that I think a warmer tone to the foreground could have helped.  I still love it.  I''m giving it a solid 9.', '2008-12-17 12:12:56.000000', NULL, 1),
(5137137, 748015, 92545, '<td valign="top">I don''t know how this one will fare among all the Christmas bokeh in this challenge, but I find it very striking.  9 from me.</td>', 'I don''t know how this one will fare among all the Christmas bokeh in this challenge, but I find it very striking.  9 from me.', '2008-12-17 12:12:57.000000', NULL, 1),
(5137140, 747263, 92545, '<td valign="top">This is definitely a top three for me.  The colors are just so vivid and the bokeh so smooth.  Great shot.</td>', 'This is definitely a top three for me.  The colors are just so vivid and the bokeh so smooth.  Great shot.', '2008-12-17 12:13:13.000000', NULL, 1),
(5137141, 747551, 92545, '<td valign="top">Definitely in my top three.  I just love everything about this.  Great shot.</td>', 'Definitely in my top three.  I just love everything about this.  Great shot.', '2008-12-17 12:13:23.000000', NULL, 1),
(5137142, 747965, 92545, '<td valign="top">I''m not entirely sure why I like this so much, but I do.  The focus is just so perfect.  I''m giving it a 9.</td>', 'I''m not entirely sure why I like this so much, but I do.  The focus is just so perfect.  I''m giving it a 9.', '2008-12-17 12:13:35.000000', NULL, 1),
(5137145, 747949, 92545, '<td valign="top">The lighting on this is just so perfect.  I love it.  8</td>', 'The lighting on this is just so perfect.  I love it.  8', '2008-12-17 12:14:30.000000', NULL, 1),
(5137146, 747827, 92545, '<td valign="top">One of my favorite ornament shots in this challege.  8</td>', 'One of my favorite ornament shots in this challege.  8', '2008-12-17 12:14:45.000000', NULL, 1),
(5137147, 747577, 92545, '<td valign="top">This is the best dandelion shot I''ve ever seen.  Great work.  8</td>', 'This is the best dandelion shot I''ve ever seen.  Great work.  8', '2008-12-17 12:14:48.000000', NULL, 1),
(5137149, 748027, 92545, '<td valign="top">One of my favorite ornament shots in this challenge.  The lights in this just mesmerize me.  I''m not even quite sure what the ornament is made of.  I love it, though.  I''m bumping it up to a 9 after a second look.</td>', 'One of my favorite ornament shots in this challenge.  The lights in this just mesmerize me.  I''m not even quite sure what the ornament is made of.  I love it, though.  I''m bumping it up to a 9 after a second look.', '2008-12-17 12:15:39.000000', NULL, 1),
(5137150, 747603, 92545, '<td valign="top">I have some similar shots from an ice storm we had last year in Oklahoma.  There''s nothing quite so beautiful (a shame that it''s so destructive) as the world encased in ice.  8</td>', 'I have some similar shots from an ice storm we had last year in Oklahoma.  There''s nothing quite so beautiful (a shame that it''s so destructive) as the world encased in ice.  8', '2008-12-17 12:15:43.000000', NULL, 1),
(5137153, 748036, 92545, '<td valign="top">One of my favorite of the ornament shots in this challenge.  The bokeh is pleasing and has such vivid color.  Nice work.  8</td>', 'One of my favorite of the ornament shots in this challenge.  The bokeh is pleasing and has such vivid color.  Nice work.  8', '2008-12-17 12:16:14.000000', NULL, 1),
(5137154, 747883, 92545, '<td valign="top">I just love the tone of this shot.  The colors are what really drew me in.  8</td>', 'I just love the tone of this shot.  The colors are what really drew me in.  8', '2008-12-17 12:16:16.000000', NULL, 1),
(5137157, 747062, 92545, '<td valign="top">Interesting shot for a bokeh challenge.  I wonder what other people think of it.  I love it.  A solid 8.</td>', 'Interesting shot for a bokeh challenge.  I wonder what other people think of it.  I love it.  A solid 8.', '2008-12-17 12:16:48.000000', NULL, 1),
(5137162, 747714, 92545, '<td valign="top">I like the tone of this shot.  After a second look, I''m bumping up to an 8.  Great shot.</td>', 'I like the tone of this shot.  After a second look, I''m bumping up to an 8.  Great shot.', '2008-12-17 12:17:47.000000', NULL, 1),
(5137167, 747129, 92545, '<td valign="top">Absolutely amazing.  If this were a wildlife challenge I''m sure I would rate this higher.  The bokeh is fine, but it''s just not what I notice in this shot.  I would LOVE to get this shot myself, though.  7</td>', 'Absolutely amazing.  If this were a wildlife challenge I''m sure I would rate this higher.  The bokeh is fine, but it''s just not what I notice in this shot.  I would LOVE to get this shot myself, though.  7', '2008-12-17 12:18:55.000000', NULL, 1),
(5137190, 748040, 100216, '<td valign="top">what is this?</td>', 'what is this?', '2008-12-17 12:25:00.000000', NULL, 1),
(5137198, 747982, 100216, '<td valign="top">this is not bokeh, this is just blurry...</td>', 'this is not bokeh, this is just blurry...', '2008-12-17 12:27:05.000000', NULL, 1),
(5137236, 747930, 68546, '<td valign="top">The framing of the bird too far to the left. The Bokeh is ok but the picture on the whole is badly composed. IMO of course :0)</td>', 'The framing of the bird too far to the left. The Bokeh is ok but the picture on the whole is badly composed. IMO of course :0)', '2008-12-17 12:50:11.000000', NULL, 1),
(5137239, 746287, 68546, '<td valign="top">There seems to be an odd colour cast, it''s very dark and leaning to the blue/green balance. Composition''s ok</td>', 'There seems to be an odd colour cast, it''s very dark and leaning to the blue/green balance. Composition''s ok', '2008-12-17 12:51:09.000000', NULL, 1),
(5137283, 746285, 3102, '<td valign="top">There is no bokeh here to speak of at all...</td>', 'There is no bokeh here to speak of at all...', '2008-12-17 13:13:58.000000', NULL, 1),
(5137311, 747865, 43774, '<td valign="top">Oh this is just so sweet!!!</td>', 'Oh this is just so sweet!!!', '2008-12-17 13:21:24.000000', NULL, 1),
(5137313, 747577, 43774, '<td valign="top">One of the best in the challenge (and I hate dandelion photos in general!).</td>', 'One of the best in the challenge (and I hate dandelion photos in general!).', '2008-12-17 13:21:43.000000', NULL, 1),
(5137317, 746461, 43774, '<td valign="top">Beautiful, if you can call a grasshopper that. Is this one of Roz''s photos? Love the bokeh as well as the sharpness and water drops.</td>', 'Beautiful, if you can call a grasshopper that. Is this one of Roz''s photos? Love the bokeh as well as the sharpness and water drops.', '2008-12-17 13:22:20.000000', NULL, 1),
(5137319, 747904, 43774, '<td valign="top">I''ve got to learn how to make different shaped bokeh. This is one of the most creative photos in the challenge, well done.</td>', 'I''ve got to learn how to make different shaped bokeh. This is one of the most creative photos in the challenge, well done.', '2008-12-17 13:22:47.000000', NULL, 1),
(5137321, 747355, 43774, '<td valign="top">Cute and creative and well lit. I love the brightness and warmth of the photo.</td>', 'Cute and creative and well lit. I love the brightness and warmth of the photo.', '2008-12-17 13:23:17.000000', NULL, 1),
(5137372, 747858, 96751, '<td valign="top">beautiful image.</td>', 'beautiful image.', '2008-12-17 13:46:50.000000', NULL, 1),
(5137410, 748022, 29440, '<td valign="top">This DNMC. You do not have any bokeh in your photo. All you have is an OOF background. That is not what the challenge calls for. Go thru the challenge photos and notice those with little circles of light just behind the main subject. Ask the SC to do a tutorial on how bokeh is created.</td>', 'This DNMC. You do not have any bokeh in your photo. All you have is an OOF background. That is not what the challenge calls for. Go thru the challenge photos and notice those with little circles of light just behind the main subject. Ask the SC to do a tutorial on how bokeh is created.', '2008-12-17 14:03:59.000000', NULL, 1),
(5137415, 747808, 29440, '<td valign="top">Where is the bokeh??? You have an OOF background and seriously doubt that this meets the challenge. Here is link that explains bokeh. //www.kenrockwell.com/tech/bokeh.htm</td>', 'Where is the bokeh??? You have an OOF background and seriously doubt that this meets the challenge. Here is link that explains bokeh. //www.kenrockwell.com/tech/bokeh.htm', '2008-12-17 14:10:57.000000', NULL, 1),
(5137427, 747953, 29440, '<td valign="top">This is one of the few good photos that show bokeh. There are so many OOF backgrounds in this challenge that do not meet the term bokeh. Yours does and the face of the dog is in good focus. I know you have to operate with a shallow DOF that causes the rest of the dog to be OOF. Did you try this in color?? 8</td>', 'This is one of the few good photos that show bokeh. There are so many OOF backgrounds in this challenge that do not meet the term bokeh. Yours does and the face of the dog is in good focus. I know you have to operate with a shallow DOF that causes the rest of the dog to be OOF. Did you try this in color?? 8', '2008-12-17 14:17:22.000000', NULL, 1),
(5137428, 747998, 29440, '<td valign="top">Very good bokeh 8</td>', 'Very good bokeh 8', '2008-12-17 14:17:29.000000', NULL, 1),
