(5138735, 747923, 15711, '<td valign="top">Oh that''s beautiful.  Would make an excellent holiday card.</td>', 'Oh that''s beautiful.  Would make an excellent holiday card.', '2008-12-18 08:51:35.000000', NULL, 1),
(5138736, 747489, 15711, '<td valign="top">ROFL</td>', 'ROFL', '2008-12-18 08:52:28.000000', NULL, 1),
