(5138849, 747917, 100495, '<td valign="top">Nice bokeh.<br/> <br/>The top right hand corner is a bit distracting though and drags my eye away from the subject.<br/> <br/>The tilt makes my twist my head to the right!</td>', 'Nice bokeh. The top right hand corner is a bit distracting though and drags my eye away from the subject. The tilt makes my twist my head to the right!', '2008-12-18 10:05:42.000000', NULL, 1),
(5138852, 747937, 100495, '<td valign="top">I''m not sure I like the abstract feeling of this.  It feels like a crop of a much bigger pic.  Would be great with a subject.</td>', 'I''m not sure I like the abstract feeling of this.  It feels like a crop of a much bigger pic.  Would be great with a subject.', '2008-12-18 10:06:51.000000', NULL, 1),
(5138854, 747869, 100495, '<td valign="top">I think the bug''s a little OOF?<br/> <br/>Nice colours throughout.</td>', 'I think the bug''s a little OOF? Nice colours throughout.', '2008-12-18 10:07:49.000000', NULL, 1),
(5138856, 746584, 100495, '<td valign="top">Might be my monitor, but I can''t make out any detail in the background.</td>', 'Might be my monitor, but I can''t make out any detail in the background.', '2008-12-18 10:08:33.000000', NULL, 1),
