INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5139626, 746677, 101707, '<td valign="top">could use more crop</td>', 'could use more crop', '2008-12-18 17:53:14.000000', NULL, 1),
(5139628, 747921, 101707, '<td valign="top">intense image</td>', 'intense image', '2008-12-18 17:53:42.000000', NULL, 1),
(5139631, 747982, 101707, '<td valign="top">very nice subject and execution</td>', 'very nice subject and execution', '2008-12-18 17:55:04.000000', NULL, 1),
(5139634, 747726, 101707, '<td valign="top">awesome</td>', 'awesome', '2008-12-18 17:55:58.000000', NULL, 1),
(5139635, 747108, 101707, '<td valign="top">nicely done</td>', 'nicely done', '2008-12-18 17:56:34.000000', NULL, 1),
(5139638, 746967, 101707, '<td valign="top">gorgeous</td>', 'gorgeous', '2008-12-18 17:57:38.000000', NULL, 1),
