(5140767, 747589, 93927, '<td valign="top">i like the angle you shot this at, it''s different. i do think the dandelion below it is kind of distracting because of it''s bold color.</td>', 'i like the angle you shot this at, it''s different. i do think the dandelion below it is kind of distracting because of it''s bold color.', '2008-12-19 11:36:20.000000', NULL, 1),
(5140769, 747865, 93927, '<td valign="top">HOW CUTE! i just want to cuddle him!</td>', 'HOW CUTE! i just want to cuddle him!', '2008-12-19 11:36:51.000000', NULL, 1),
(5140770, 747262, 93927, '<td valign="top">this is beautiful. the rim lighting on that plant is perfect. nice work!</td>', 'this is beautiful. the rim lighting on that plant is perfect. nice work!', '2008-12-19 11:38:11.000000', NULL, 1),
(5140772, 747530, 93927, '<td valign="top">lovely detail in the eyes and fur!</td>', 'lovely detail in the eyes and fur!', '2008-12-19 11:38:33.000000', NULL, 1),
(5140774, 747129, 93927, '<td valign="top">his expression made me laugh! cool capture!</td>', 'his expression made me laugh! cool capture!', '2008-12-19 11:39:17.000000', NULL, 1),
(5140775, 747791, 93927, '<td valign="top">cool, really stands out amongst the christmas images :P nicely done.</td>', 'cool, really stands out amongst the christmas images :P nicely done.', '2008-12-19 11:40:17.000000', NULL, 1),
(5140778, 748029, 93927, '<td valign="top">cool image. i wish the ornament stuck out a little more, i feel like the lights in the background are more dominate in the image. if the ornament was a bit brighter then it would be a knockout. good luck :)</td>', 'cool image. i wish the ornament stuck out a little more, i feel like the lights in the background are more dominate in the image. if the ornament was a bit brighter then it would be a knockout. good luck :)', '2008-12-19 11:42:36.000000', NULL, 1),
(5140779, 747037, 93927, '<td valign="top">hahahaha look at that little tongue! nice find!</td>', 'hahahaha look at that little tongue! nice find!', '2008-12-19 11:43:12.000000', NULL, 1),
(5140781, 746812, 93927, '<td valign="top">cool shot, well done!</td>', 'cool shot, well done!', '2008-12-19 11:43:40.000000', NULL, 1),
