(5142238, 747933, 97893, '<td valign="top">Superb capture! Beautiful Bokeh too! .9.</td>', 'Superb capture! Beautiful Bokeh too! .9.', '2008-12-20 03:16:27.000000', NULL, 1),
(5142239, 747524, 97893, '<td valign="top">Very nice aesthetics in this shot. 9.</td>', 'Very nice aesthetics in this shot. 9.', '2008-12-20 03:16:53.000000', NULL, 1),
(5142240, 748015, 97893, '<td valign="top">Excellent capture! .9.</td>', 'Excellent capture! .9.', '2008-12-20 03:17:16.000000', NULL, 1),
(5142343, 747963, 43774, '<td valign="top">The wind in the tree has given this a whispy, airy feeling, very cool. Some of the snowflakes are a bit too bright for my liking but it''s an interetsing photo.</td>', 'The wind in the tree has given this a whispy, airy feeling, very cool. Some of the snowflakes are a bit too bright for my liking but it''s an interetsing photo.', '2008-12-20 08:50:32.000000', NULL, 1),
(5142344, 747589, 43774, '<td valign="top">Would prefer the background dandelion to be in a different spot and not obstructed by the top dandelion. But a nice clear photo.</td>', 'Would prefer the background dandelion to be in a different spot and not obstructed by the top dandelion. But a nice clear photo.', '2008-12-20 08:51:09.000000', NULL, 1),
(5142346, 747354, 43774, '<td valign="top">A pretty ornament, very clear photo, nice.</td>', 'A pretty ornament, very clear photo, nice.', '2008-12-20 08:51:32.000000', NULL, 1),
(5142348, 747738, 43774, '<td valign="top">What an interesting looking insect! Very clear and sharp, great colours.</td>', 'What an interesting looking insect! Very clear and sharp, great colours.', '2008-12-20 08:51:53.000000', NULL, 1),
(5142351, 746677, 43774, '<td valign="top">Very nice colours especially on the beetle. A bit of noise reduction (such a neat image or noise ninja) would do wonders for this photo.</td>', 'Very nice colours especially on the beetle. A bit of noise reduction (such a neat image or noise ninja) would do wonders for this photo.', '2008-12-20 08:53:08.000000', NULL, 1),
(5142497, 747218, 99981, '<td valign="top">Well...i like the details on the bee, but i think she''s a little noisy. The bokeh is just ok, because it seems a little rigid for me...i can''t see that smooth or creamy aspects on it. Sorry if i was rude with something, i like your shot, but i think it could be much better.</td>', 'Well...i like the details on the bee, but i think she''s a little noisy. The bokeh is just ok, because it seems a little rigid for me...i can''t see that smooth or creamy aspects on it. Sorry if i was rude with something, i like your shot, but i think it could be much better.', '2008-12-20 11:02:43.000000', NULL, 1),
(5142499, 747865, 99981, '<td valign="top">The balls are really distractive an the bunny is just a little bit out of focus. I actually like the bokeh, but i think it would be shown better in another perspective.</td>', 'The balls are really distractive an the bunny is just a little bit out of focus. I actually like the bokeh, but i think it would be shown better in another perspective.', '2008-12-20 11:04:44.000000', NULL, 1),
(5142558, 747541, 73942, '<td valign="top">very pretty colors</td>', 'very pretty colors', '2008-12-20 11:41:20.000000', NULL, 1),
