(5143953, 746553, 99981, '<td valign="top">The bokeh is good, but the photo is not very interesting, maybe because of the object, which is too hidden. With another perspective showing all the dog''s head and a better bokeh background you would have a great shot there! Good luck!</td>', 'The bokeh is good, but the photo is not very interesting, maybe because of the object, which is too hidden. With another perspective showing all the dog''s head and a better bokeh background you would have a great shot there! Good luck!', '2008-12-21 12:14:15.000000', NULL, 1),
(5143956, 747837, 99981, '<td valign="top">Great colors and good border. The focus on the rose could be better! The light is cool and the bokeh too, maybe it could be less sharpened.</td>', 'Great colors and good border. The focus on the rose could be better! The light is cool and the bokeh too, maybe it could be less sharpened.', '2008-12-21 12:17:45.000000', NULL, 1),
(5143961, 747259, 99981, '<td valign="top">There are too many parts without focus on your shot and this makes confused about which is the main object. The colors are good and the bokeh is good too, but it got confused by the "non-focused" areas too.</td>', 'There are too many parts without focus on your shot and this makes confused about which is the main object. The colors are good and the bokeh is good too, but it got confused by the "non-focused" areas too.', '2008-12-21 12:21:22.000000', NULL, 1),
(5143965, 747962, 99981, '<td valign="top">Too noisy and the colors are kind of dead. Maybe giving more emphasis to the flower and taking out those trunks would be better. The bokeh is good bot needs more tweaking.</td>', 'Too noisy and the colors are kind of dead. Maybe giving more emphasis to the flower and taking out those trunks would be better. The bokeh is good bot needs more tweaking.', '2008-12-21 12:25:57.000000', NULL, 1),
(5143980, 747858, 99981, '<td valign="top">Well...i like the bokeh, but i wouldn''t know what the main object is if you haven''t told me title. But i like the perspective and the difference between colors from the left to the right! Good job!</td>', 'Well...i like the bokeh, but i wouldn''t know what the main object is if you haven''t told me title. But i like the perspective and the difference between colors from the left to the right! Good job!', '2008-12-21 12:35:17.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5144008, 747960, 99981, '<td valign="top">Nice bokeh. It''s a little OOF but it''s a beatiful photo. Nice colors too.</td>', 'Nice bokeh. It''s a little OOF but it''s a beatiful photo. Nice colors too.', '2008-12-21 12:47:51.000000', NULL, 1),
(5144011, 747856, 99981, '<td valign="top">I don''t see a good bokeh there. The sky looks a little noisy too, but it''s a good photo of the moon.</td>', 'I don''t see a good bokeh there. The sky looks a little noisy too, but it''s a good photo of the moon.', '2008-12-21 12:48:37.000000', NULL, 1),
(5144015, 747989, 99981, '<td valign="top">The star looks OOF and a little dark, the colors are good, so as the bokeh. Try a theme less expected next time! Sorry if i was rude. Good luck!</td>', 'The star looks OOF and a little dark, the colors are good, so as the bokeh. Try a theme less expected next time! Sorry if i was rude. Good luck!', '2008-12-21 12:51:07.000000', NULL, 1),
(5144122, 747263, 68916, '<td valign="top">beautiful, great colors and nice detail.   one of my favorites.</td>', 'beautiful, great colors and nice detail.   one of my favorites.', '2008-12-21 13:39:14.000000', NULL, 1),
(5144123, 747551, 68916, '<td valign="top">really nice!</td>', 'really nice!', '2008-12-21 13:39:29.000000', NULL, 1),
