(5144126, 747942, 39110, '<td valign="top">OMG this is simply wonderful 10 and a FAVE :)</td>', 'OMG this is simply wonderful 10 and a FAVE :)', '2008-12-21 13:41:10.000000', NULL, 1),
(5144186, 747808, 75585, '<td valign="top">I have to take a stab at how this worked in basic - I think you laid the phone on a monitor/screen and took the picture?</td>', 'I have to take a stab at how this worked in basic - I think you laid the phone on a monitor/screen and took the picture?', '2008-12-21 14:48:18.000000', NULL, 1),
(5144474, 748040, 88580, '<td valign="top">The border is too subtle.  A one-by-one pixel window in the matte would have been more effective.  No one likes a half-assed wise ass.  :)  10 for effort, though.</td>', 'The border is too subtle.  A one-by-one pixel window in the matte would have been more effective.  No one likes a half-assed wise ass.  :)  10 for effort, though.', '2008-12-21 18:31:33.000000', NULL, 1),
