(5147235, 747965, 94235, '<td valign="top">Good colour, depth of field and clarity. Over all a very pleasing photograph on the eye. ( And that is the way we spell colour down here in Oz if any one is wondering)</td>', 'Good colour, depth of field and clarity. Over all a very pleasing photograph on the eye. ( And that is the way we spell colour down here in Oz if any one is wondering)', '2008-12-23 02:34:28.000000', NULL, 1),
(5147237, 747863, 94235, '<td valign="top">The background compliments the main subject, well done.</td>', 'The background compliments the main subject, well done.', '2008-12-23 02:36:04.000000', NULL, 1),
(5147238, 746956, 94235, '<td valign="top">The bokeh highlight on the bottle is a nice touch, good shot.</td>', 'The bokeh highlight on the bottle is a nice touch, good shot.', '2008-12-23 02:37:09.000000', NULL, 1),
(5147239, 747879, 94235, '<td valign="top">The cropping compliments this already nice shot.</td>', 'The cropping compliments this already nice shot.', '2008-12-23 02:39:17.000000', NULL, 1),
(5147240, 747603, 94235, '<td valign="top">The patchwork background makes this look like a bit like a puzzle. Nice work.</td>', 'The patchwork background makes this look like a bit like a puzzle. Nice work.', '2008-12-23 02:39:34.000000', NULL, 1),
