(5147243, 747901, 94235, '<td valign="top">Maybe me, but a little more clarity on the bud would have been better but the bokeh is excellent, well done.</td>', 'Maybe me, but a little more clarity on the bud would have been better but the bokeh is excellent, well done.', '2008-12-23 02:44:00.000000', NULL, 1),
(5147244, 747865, 94235, '<td valign="top">My wife (a rabbit lover) adores this shot. So do I!</td>', 'My wife (a rabbit lover) adores this shot. So do I!', '2008-12-23 02:45:20.000000', NULL, 1),
(5147245, 747956, 94235, '<td valign="top">Beautiful bokeh up top but would have liked to have seen that effect all the way down the left side for balance.Nice shot all the same.</td>', 'Beautiful bokeh up top but would have liked to have seen that effect all the way down the left side for balance.Nice shot all the same.', '2008-12-23 02:48:04.000000', NULL, 1),
(5147247, 747943, 94235, '<td valign="top">Great subject clarity and a nice bokeh.</td>', 'Great subject clarity and a nice bokeh.', '2008-12-23 02:49:13.000000', NULL, 1),
