(5147402, 747977, 97893, '<td valign="top">I have a comment on this shot, particularly because it has been ''sighted very well'' and beautifully composed. This means that you have a wonderful photographer''s eye. But there is something amiss. The DOF that you selected<br/>and the focus of the shot has made it a bit cluttered in foreground - or so it appears to me. <br/> <br/>.7.</td>', 'I have a comment on this shot, particularly because it has been ''sighted very well'' and beautifully composed. This means that you have a wonderful photographer''s eye. But there is something amiss. The DOF that you selectedand the focus of the shot has made it a bit cluttered in foreground - or so it appears to me.  .7.', '2008-12-23 09:09:29.000000', NULL, 1),
(5147526, 747943, 101847, '<td valign="top">This is a very fine photo - in particular, I *love* the green frame for the head!</td>', 'This is a very fine photo - in particular, I *love* the green frame for the head!', '2008-12-23 10:37:53.000000', NULL, 1),
(5147557, 747551, 35034, '<td valign="top">I really like your color and composition, but wish for more contrast of focus between the flower and background.  Still a nice photo, but it might have more punch with a non-blury subject...</td>', 'I really like your color and composition, but wish for more contrast of focus between the flower and background.  Still a nice photo, but it might have more punch with a non-blury subject...', '2008-12-23 11:12:21.000000', NULL, 1),
(5147562, 747037, 35034, '<td valign="top">An excellent bokeh effect.  I would like the overall effect more with a more clearly defined subject.  Too bad you caught the deer in light that was so close in value to the background.  Good shot!</td>', 'An excellent bokeh effect.  I would like the overall effect more with a more clearly defined subject.  Too bad you caught the deer in light that was so close in value to the background.  Good shot!', '2008-12-23 11:17:59.000000', NULL, 1),
(5147569, 748018, 98939, '<td valign="top">why is she naked in the snow?!?!?!</td>', 'why is she naked in the snow?!?!?!', '2008-12-23 11:32:04.000000', NULL, 1),
(5147601, 747774, 35034, '<td valign="top">Very nice!  You have done a great job of contrasting the subject with the blurred background--clearly difficult, based on the majority of pics in this challenge.  Great job!</td>', 'Very nice!  You have done a great job of contrasting the subject with the blurred background--clearly difficult, based on the majority of pics in this challenge.  Great job!', '2008-12-23 12:10:33.000000', NULL, 1),
(5147620, 747620, 35034, '<td valign="top">Hmmm...  Thoroughbred Park in Lexington?  Nice picture!  It could perhaps use a bit more contrast between subject horse and background, but the atmosphere of this is lovely.</td>', 'Hmmm...  Thoroughbred Park in Lexington?  Nice picture!  It could perhaps use a bit more contrast between subject horse and background, but the atmosphere of this is lovely.', '2008-12-23 12:20:33.000000', NULL, 1),
(5147683, 747779, 99981, '<td valign="top">The title could be more interesting, maybe to make us imagine something with Jeff''s look. I like the bokeh.</td>', 'The title could be more interesting, maybe to make us imagine something with Jeff''s look. I like the bokeh.', '2008-12-23 13:20:01.000000', NULL, 1),
(5147688, 747268, 99981, '<td valign="top">Nice one! Great red and creative idea!</td>', 'Nice one! Great red and creative idea!', '2008-12-23 13:22:33.000000', NULL, 1),
(5148346, 747984, 54446, '<td valign="top">Wonderful colors and bokeh.  One of my favorites in this challenge.  Should ribbon!  (10)</td>', 'Wonderful colors and bokeh.  One of my favorites in this challenge.  Should ribbon!  (10)', '2008-12-23 19:20:56.000000', NULL, 1),
(5148347, 747965, 54446, '<td valign="top">Great colors, excellent selective focus.  My favorite in this challenge.  (10)</td>', 'Great colors, excellent selective focus.  My favorite in this challenge.  (10)', '2008-12-23 19:21:02.000000', NULL, 1),
(5148348, 748024, 54446, '<td valign="top">Good composition.  A memorable and striking image.  Effective and variable blurred bg.  (10)</td>', 'Good composition.  A memorable and striking image.  Effective and variable blurred bg.  (10)', '2008-12-23 19:21:10.000000', NULL, 1),
(5148349, 747105, 54446, '<td valign="top">Very pretty image w/ outstanding composition.  Interesting to see the light reflections on the glass table in some degree of bokeh blur as the background.  (10)</td>', 'Very pretty image w/ outstanding composition.  Interesting to see the light reflections on the glass table in some degree of bokeh blur as the background.  (10)', '2008-12-23 19:21:29.000000', NULL, 1),
(5148351, 747988, 54446, '<td valign="top">Excellent exposure and bokeh light circles behind.  Meets the challenge well.  (9)</td>', 'Excellent exposure and bokeh light circles behind.  Meets the challenge well.  (9)', '2008-12-23 19:21:34.000000', NULL, 1),
(5148352, 747750, 54446, '<td valign="top">Very eye-pleasing image with a Christmas decorations theme.  My favorite of this ilk.  (9)</td>', 'Very eye-pleasing image with a Christmas decorations theme.  My favorite of this ilk.  (9)', '2008-12-23 19:21:45.000000', NULL, 1),
(5148353, 747779, 54446, '<td valign="top">First rate image.  Excellent exposure control.  I consider the bg to be an excellent bokeh!  (9)</td>', 'First rate image.  Excellent exposure control.  I consider the bg to be an excellent bokeh!  (9)', '2008-12-23 19:21:47.000000', NULL, 1),
